1	import { db } from "@/lib/db";
2	import { requireUser } from "@/lib/auth";
3	import { scanForSecrets } from "@/lib/secret-scan";
4	import { blockingFindings, moderateForPublish, recordModerationFindings } from "@/lib/moderation";
5	import { checkPublishRateLimit } from "@/lib/rate-limit";
6	import { track, EVENTS } from "@/lib/events";
7	import { FLAGS, isEnabled } from "@/lib/flags";
8	
9	export const dynamic = "force-dynamic";
10	
11	const SITES_BASE = process.env.KODELY_SITES_BASE ?? "kodely.site";
12	
13	// Publishing snapshots the draft tree onto the published tree. Deliberately
14	// NOT deploying to real Nxeon hosting infra in Phase 1 — that provisioner is
15	// still gated (see the Nxeon shared-hosting security review), so *.kodely.site
16	// is served straight out of this app from the published rows.
17	//
18	// The *.kodely.site wildcard's nginx block only routes to the PROD app
19	// (port 3000) — there is no separate wildcard for staging. A project
20	// published from staging would otherwise return a *.kodely.site URL that
21	// resolves through prod's app against prod's database, where the slug
22	// doesn't exist. Deriving the mode from the request's own Host header (never
23	// touches DNS, nginx, or .env) means staging always gets a URL that resolves
24	// against itself.
25	export async function POST(req: Request, { params }: { params: Promise<{ id: string }> }) {
26	  const user = await requireUser().catch(() => null);
27	  if (!user) return Response.json({ error: "Not signed in." }, { status: 401 });
28	  const { id } = await params;
29	
30	  const project = await db.project.findFirst({
31	    where: { id, userId: user.id },
32	    include: {
33	      files: { where: { published: false, kind: "build" } },
34	    },
35	  });
36	  if (!project) return Response.json({ error: "Project not found." }, { status: 404 });
37	
38	  // ── Kill switch ──────────────────────────────────────────────────────────
39	  // After the project lookup (an unknown or someone else's project still 404s)
40	  // and ahead of everything that follows: the publish rate limit, the secret
41	  // scan, moderation, and the transaction that copies the build tree onto the
42	  // published rows. That transaction is the moment the files become reachable
43	  // at *.kodely.site, so this is the one gate that has to hold when the switch
44	  // exists precisely because something abusive is already public.
45	  //
46	  // Ahead of the "nothing to publish yet" 400 as well. Both answers are true
47	  // when both apply, and during an incident the switch is the more useful of
48	  // the two — it tells the user the state of the world rather than the state
49	  // of their draft.
50	  //
51	  // Subject: user.id. The table hands this one no subject, but the project
52	  // owner is right here and passing them is strictly better — it is what makes
53	  // any rolloutPct below 100 a stable per-user split instead of a full shed
54	  // (see the `if (!userId) return false` note in lib/flags.ts). At the only
55	  // setting a kill switch should ever be operated at — 100%, toggled with
56	  // `enabled` — it changes nothing.
57	  if (!(await isEnabled(FLAGS.publishing, user.id))) {
58	    return Response.json(
59	      {
60	        error:
61	          "Publishing is paused right now while we work through an issue. Your site is saved and nothing has changed — try publishing again shortly.",
62	      },
63	      { status: 503 },
64	    );
65	  }
66	
67	  if (project.files.length === 0) {
68	    return Response.json({ error: "Nothing to publish yet — generate a site first." }, { status: 400 });
69	  }
70	
71	  // Only gate genuinely new subdomains — republishing an already-live project
72	  // isn't the spam-farming vector this protects against.
73	  if (!project.publishedAt) {
74	    const rateLimit = await checkPublishRateLimit(user.id);
75	    if (!rateLimit.allowed) {
76	      return Response.json(
77	        { error: "You've published a lot of new sites today — try again tomorrow." },
78	        { status: 429, headers: { "Retry-After": String(rateLimit.retryAfterSeconds) } },
79	      );
80	    }
81	  }
82	
83	  // Scan both the compiled output (what's actually served) and the source
84	  // (a comment or string that got stripped by the build can still leak if
85	  // someone reads it another way) — belt and suspenders, cheap either way.
86	  const sourceFiles = await db.projectFile.findMany({
87	    where: { projectId: id, published: false, kind: "source" },
88	  });
89	  const publishable = [...project.files, ...sourceFiles].map((f) => ({
90	    path: f.path,
91	    content: f.content,
92	  }));
93	
94	  const leaks = scanForSecrets(publishable);
95	  if (leaks.length > 0) {
96	    const { path, kind } = leaks[0];
97	    return Response.json(
98	      { error: `Publishing blocked: found what looks like a real secret in ${path} (${kind}). Remove it and try again.` },
99	      { status: 400 },
100	    );
101	  }
102	
103	  // Abuse check. Same last-gate position as the secret scan, for the same
104	  // reason: after this line the files are reachable at *.kodely.site by anyone,
105	  // and a phishing clone hosted there is Kodely's abuse report to answer.
106	  //
107	  // moderateForPublish returns SIGNALS, not a verdict (see lib/moderation.ts) —
108	  // policy is applied right here, and only `high` refuses. Everything below
109	  // `high` is expected to be mostly benign (an integration logo, a mock login
110	  // UI) and must not stand between a legitimate user and their own site.
111	  const moderation = await moderateForPublish(publishable);
112	  const blockers = blockingFindings(moderation);
113	
114	  // Record BEFORE the policy branch, so the blocked path cannot return without
115	  // its rows: a refused publish leaves no other trace anywhere: no published
116	  // files, no event, nothing on the project. These rows are the only evidence
117	  // it happened.
118	  //
119	  // Awaited, not fire-and-forget like track() above — the full argument is on
120	  // recordModerationFindings() in lib/moderation.ts. The short version: this is
121	  // a moderation record about one identifiable site, not an aggregate metric,
122	  // a floating promise is not guaranteed to complete once we return a Response,
123	  // and the call cannot throw or change the outcome either way. Whatever this
124	  // line does, the publish below behaves exactly as it did before it existed.
125	  await recordModerationFindings({ projectId: id, result: moderation, blocked: blockers });
126	
127	  if (blockers.length > 0) {
128	    const worst = blockers[0];
129	    console.warn(
130	      `[kodely] publish blocked by moderation project=${id} user=${user.id} provider=${moderation.provider}`,
131	      blockers.map((f) => ({ rule: f.rule, path: f.path, evidence: f.evidence })),
132	    );
133	    return Response.json(
134	      {
135	        error: `Publishing blocked: ${worst.note} (${worst.path} — "${worst.evidence}"). If this is a mistake, edit the page or reply here and we'll take a look.`,
136	        moderation: { rule: worst.rule, path: worst.path },
137	      },
138	      { status: 400 },
139	    );
140	  }
141	  if (moderation.findings.length > 0) {
142	    // ModerationFinding is now the durable record; this stays as an operational
143	    // breadcrumb and is the one place that still shows EVERY occurrence. The
144	    // table records a non-blocking finding once per distinct (rule, file,
145	    // snippet) and skips exact repeats on republish — see the volume note in
146	    // lib/moderation.ts — so "fired again on an unchanged page" is a log
147	    // question, not a query.
148	    console.warn(
149	      `[kodely] publish moderation signals project=${id} user=${user.id} provider=${moderation.provider}`,
150	      moderation.findings.map((f) => ({ rule: f.rule, severity: f.severity, path: f.path })),
151	    );
152	  }
153	
154	  await db.$transaction([
155	    db.projectFile.deleteMany({ where: { projectId: id, published: true, kind: "build" } }),
156	    db.projectFile.createMany({
157	      data: project.files.map((f) => ({
158	        projectId: id,
159	        path: f.path,
160	        content: f.content,
161	        published: true,
162	        kind: "build",
163	      })),
164	    }),
165	    db.project.update({ where: { id }, data: { publishedAt: new Date() } }),
166	  ]);
167	
168	  // The North Star. `firstPublish` separates "reached the promise for the
169	  // first time" from a routine republish — the funnel counts the former.
170	  track(EVENTS.sitePublished, {
171	    userId: user.id,
172	    props: {
173	      projectId: id,
174	      slug: project.slug,
175	      firstPublish: !project.publishedAt,
176	      files: project.files.length,
177	    },
178	  });
179	
180	  const host = req.headers.get("host") ?? "";
181	  const url = host.includes("staging")
182	    ? `https://${host}/api/site/${project.slug}`
183	    : `https://${project.slug}.${SITES_BASE}`;
184	
185	  return Response.json({ url });
186	}
187

1	/**
2	 * The only place in Kodely that opens a socket to an address a user chose.
3	 *
4	 * Not a route — a module colocated with the one route that uses it, so that the
5	 * network half of the site import stays out of `lib/site-import.ts` (which has
6	 * to stay importable from a browser bundle) and so that everything with a
7	 * `node:` import is in one file that can be read top to bottom.
8	 *
9	 * ## Read this before changing anything below
10	 *
11	 * The process running this code holds DATABASE_URL, STRIPE_SECRET_KEY and
12	 * ANTHROPIC_API_KEY, and it sits inside a private network. An SSRF here is not
13	 * "an unwanted HTTP request", it is credential disclosure. Every control below
14	 * is written on the assumption that the caller is trying to reach
15	 * 169.254.169.254, and several of them exist only because the obvious
16	 * implementation (`fetch(userUrl)`) is wrong in a way that looks right.
17	 *
18	 * ## What is defended, and how
19	 *
20	 *  1. SCHEME + PORT + CREDENTIALS + HOSTNAME SHAPE — `validateImportUrl` in
21	 *     lib/site-import.ts, before anything resolves.
22	 *
23	 *  2. DNS IS RESOLVED HERE, EXPLICITLY, and every address that comes back is
24	 *     classified. Not the hostname — the addresses. A hostname allowlist or
25	 *     denylist is decoration: `evil.test` is a public name and its A record is
26	 *     whatever the attacker's zone file says today.
27	 *
28	 *  3. EVERY answer must be public, not merely the one we pick. A name that
29	 *     publishes 93.184.216.34 and 10.0.0.5 together is either broken or an
30	 *     attack, and picking the good one would mean the same lookup a moment
31	 *     later could hand a different answer to something else.
32	 *
33	 *  4. THE REBIND HOLE IS CLOSED BY PINNING. This is the control most
34	 *     implementations miss, so it is worth being explicit about the failure it
35	 *     prevents. The naive shape is:
36	 *
37	 *         const ips = await dns.resolve(host);   // 93.184.216.34 — fine
38	 *         if (ips.every(isPublic)) await fetch(url);   // resolves AGAIN
39	 *
40	 *     Two lookups, and the attacker controls the TTL. Set it to 0 and answer
41	 *     the first query with a public address and the second with 169.254.169.254
42	 *     and every check passed while the socket went somewhere else. It is not
43	 *     even a race you have to win reliably — the attacker just retries.
44	 *
45	 *     The fix is that THERE IS ONLY ONE LOOKUP. `pinnedLookup` below is handed
46	 *     to `https.request` as its resolver, and it ignores the hostname entirely
47	 *     and returns the single address this code already validated. The TCP
48	 *     connection provably goes to the address that was checked, because no
49	 *     second resolution exists to disagree with the first. TLS still validates
50	 *     the certificate against the real hostname (`servername`), and the `Host`
51	 *     header still carries the real hostname, so virtual hosting works and the
52	 *     server sees a completely ordinary request.
53	 *
54	 *  5. REDIRECTS ARE FOLLOWED BY HAND. `https.request` does not follow them at
55	 *     all, which is one reason it is used here instead of `fetch` — `fetch`
56	 *     follows by default, and a permitted host answering
57	 *     `Location: http://169.254.169.254/latest/meta-data/` is the single most
58	 *     common way a "validated" fetcher gets walked. Each hop goes back through
59	 *     `resolveRedirect` (full URL validation) and then through this function
60	 *     again (fresh DNS, fresh classification, fresh pin). Capped at
61	 *     MAX_REDIRECTS.
62	 *
63	 *  6. BOUNDED. A 5s connect timeout, a 10s deadline over the WHOLE operation
64	 *     including robots.txt and every hop, a body cap enforced byte by byte
65	 *     while the response streams, and a redirect count. `Content-Length` is
66	 *     used only as an early reject — never as the thing that stops the read,
67	 *     because a hostile server will happily send a 12-byte Content-Length and
68	 *     then stream forever.
69	 *
70	 *  7. CONTENT-TYPE ALLOWLIST. `text/html` for a page. Anything else is refused
71	 *     before the body is read, so an internal service that answers JSON never
72	 *     gets its answer into our process.
73	 *
74	 *  8. THE BODY NEVER LEAVES THIS PROCESS. The route returns the parsed struct
75	 *     and nothing else — no raw HTML to the client, no raw HTML to the model.
76	 *
77	 * ## The control this file CANNOT provide
78	 *
79	 * Blast radius. Everything above is a filter, and a filter can have a bug: a
80	 * parsing quirk, an IPv6 form nobody tested, a redirect path that skips a
81	 * check. The mitigation that does not depend on getting the filter right is
82	 * running the fetch somewhere that has nothing worth stealing — a separate
83	 * worker with no database URL, no Anthropic key, no Stripe key, egress
84	 * restricted at the network layer, talking to the app over a narrow internal
85	 * endpoint. That is infrastructure, not code, and it does not exist yet.
86	 *
87	 * So `isUrlImportConfigured()` FAILS CLOSED: the URL path is off unless
88	 * KODELY_SITE_IMPORT_EGRESS is explicitly set, and the name is the egress
89	 * service rather than the feature on purpose — the switch should be turned on
90	 * by whoever stands that service up, not by whoever wants the feature. The
91	 * paste path in the wizard needs none of this and is always on.
92	 */
93	
94	import { lookup as dnsLookup } from "node:dns/promises";
95	import https from "node:https";
96	import type { IncomingMessage } from "node:http";
97	import type { LookupAddress } from "node:dns";
98	import type { LookupFunction } from "node:net";
99	
100	import {
101	  classifyAddress,
102	  IMPORT_LIMITS,
103	  resolveRedirect,
104	  validateImportUrl,
105	} from "@/lib/site-import";
106	
107	// ---------------------------------------------------------------------------
108	// Identity
109	// ---------------------------------------------------------------------------
110	
111	/**
112	 * An identifiable user agent, because a fetcher that arrives anonymously is a
113	 * machine for generating abuse reports nobody can answer. The contact URL is a
114	 * real page today; a dedicated `/bot` page explaining what this is and how to
115	 * block it would be better and is a one-page follow-up outside this change's
116	 * scope.
117	 */
118	const CONTACT_URL = `${(process.env.APP_URL ?? "https://kodely.me").replace(/\/+$/, "")}/contact`;
119	export const USER_AGENT = `KodelySiteImport/1.0 (+${CONTACT_URL})`;
120	/** The token a robots.txt author would write to address us specifically. */
121	const ROBOTS_TOKEN = "kodelysiteimport";
122	
123	/**
124	 * The gate. Off unless an operator says otherwise — see the header.
125	 *
126	 * Deliberately an environment variable rather than a `lib/flags.ts` key. Two
127	 * reasons: `FLAGS` is a closed vocabulary in a file this change is not allowed
128	 * to touch, and more importantly a database-backed flag is the wrong shape for
129	 * this particular switch. A FeatureFlag row can be flipped from an admin page
130	 * by someone who does not know whether the egress worker exists; an environment
131	 * variable can only be set by whoever deploys the process, which is the same
132	 * person who would have stood the worker up. When this feature graduates, the
133	 * right end state is BOTH: this variable for "the isolated egress path exists",
134	 * and a `feature.prompt_wizard_import` flag with a rolloutPct for "how many
135	 * users see it".
136	 */
137	export function isUrlImportConfigured(): boolean {
138	  const value = (process.env.KODELY_SITE_IMPORT_EGRESS ?? "").trim().toLowerCase();
139	  return value === "1" || value === "true" || value === "on";
140	}
141	
142	// ---------------------------------------------------------------------------
143	// Results
144	// ---------------------------------------------------------------------------
145	
146	export type FetchFailure =
147	  /** Refused before any packet left the box. The URL or an address was bad. */
148	  | "blocked"
149	  /** The remote end was slow, unreachable, or the deadline expired. */
150	  | "unreachable"
151	  /** It answered, but not with an HTML page we can read. */
152	  | "unusable"
153	  /** robots.txt says not to. */
154	  | "robots";
155	
156	export type FetchResult =
157	  | {
158	      ok: true;
159	      html: string;
160	      /** After redirects. This is what provenance is recorded against. */
161	      finalUrl: string;
162	      /** Every URL in the chain, for the audit log. */
163	      hops: string[];
164	      /** Every address actually connected to, in hop order, for the audit log. */
165	      addresses: string[];
166	    }
167	  | { ok: false; code: FetchFailure; reason: string };
168	
169	type Hop = {
170	  status: number;
171	  headers: IncomingMessage["headers"];
172	  body: Buffer;
173	  address: string;
174	};
175	
176	// ---------------------------------------------------------------------------
177	// One request, to one validated address
178	// ---------------------------------------------------------------------------
179	
180	/**
181	 * Resolve `hostname` and return the ONE address every later step will use.
182	 *
183	 * Fails if the name does not resolve, if any answer is non-public, or if the
184	 * lookup outlives the deadline. `verbatim: true` keeps the resolver's own
185	 * ordering rather than Node's v4-first reshuffle — irrelevant to safety (both
186	 * families are classified) but it means we connect to what the OS would have.
187	 */
188	async function resolveOne(
189	  hostname: string,
190	  deadline: number,
191	): Promise<{ ok: true; address: string; family: number } | { ok: false; code: FetchFailure; reason: string }> {
192	  let answers: LookupAddress[];
193	  try {
194	    answers = (await withDeadline(
195	      dnsLookup(hostname, { all: true, verbatim: true }),
196	      deadline,
197	      "DNS",
198	    )) as LookupAddress[];
199	  } catch {
200	    return { ok: false, code: "unreachable", reason: "We couldn't look that domain up." };
201	  }
202	  if (!answers.length) {
203	    return { ok: false, code: "unreachable", reason: "That domain doesn't resolve to anything." };
204	  }
205	
206	  for (const answer of answers) {
207	    const verdict = classifyAddress(answer.address);
208	    if (!verdict.ok) {
209	      // The whole name is refused, not just this record. A name that publishes
210	      // one private address is not a name we want to be talking to at all, and
211	      // "pick the public one" would mean the next lookup could differ.
212	      return { ok: false, code: "blocked", reason: verdict.reason };
213	    }
214	  }
215	
216	  const chosen = answers[0];
217	  return { ok: true, address: chosen.address, family: chosen.family };
218	}
219	
220	/**
221	 * A resolver that does not resolve.
222	 *
223	 * This is the whole TOCTOU fix in six lines: `https.request` is given this as
224	 * its `lookup`, so the connection layer never performs a second DNS query and
225	 * has no opportunity to receive a different answer. The hostname argument is
226	 * ignored on purpose — it is the same hostname we already resolved, and reading
227	 * it here would only invite someone to "helpfully" re-resolve it later.
228	 *
229	 * Both callback shapes are handled because `net.connect` calls a custom lookup
230	 * with `all: true` when Happy Eyeballs is in play and with `all: false`
231	 * otherwise, and which one you get has changed between Node versions.
232	 */
233	function pinnedLookup(address: string, family: number): LookupFunction {
234	  return (_hostname, options, callback) => {
235	    if (options && typeof options === "object" && options.all) {
236	      callback(null, [{ address, family }]);
237	    } else {
238	      callback(null, address, family);
239	    }
240	  };
241	}
242	
243	/** Reject a promise that outlives the operation's wall clock. */
244	async function withDeadline<T>(promise: Promise<T>, deadline: number, what: string): Promise<T> {
245	  const remaining = deadline - Date.now();
246	  if (remaining <= 0) throw new Error(`${what} deadline expired`);
247	  let timer: NodeJS.Timeout | undefined;
248	  try {
249	    return await Promise.race([
250	      promise,
251	      new Promise<never>((_, reject) => {
252	        timer = setTimeout(() => reject(new Error(`${what} timed out`)), remaining);
253	      }),
254	    ]);
255	  } finally {
256	    if (timer) clearTimeout(timer);
257	  }
258	}
259	
260	/**
261	 * GET one URL, at one pre-validated address, with no redirect following and a
262	 * hard byte cap.
263	 *
264	 * The cap is enforced in the `data` handler and the socket is destroyed the
265	 * moment it is breached, so a server that streams forever costs us
266	 * `maxBytes + one chunk` of memory and nothing more. `Content-Length` is
267	 * consulted first purely as an optimisation: a declared size over the cap lets
268	 * us hang up before reading anything, and a declared size UNDER the cap buys no
269	 * trust at all.
270	 */
271	function getOnce(
272	  url: URL,
273	  address: string,
274	  family: number,
275	  maxBytes: number,
276	  deadline: number,
277	): Promise<Hop> {
278	  return new Promise<Hop>((resolve, reject) => {
279	    const budget = deadline - Date.now();
280	    if (budget <= 0) {
281	      reject(new Error("deadline expired"));
282	      return;
283	    }
284	
285	    const req = https.request({
286	      protocol: "https:",
287	      host: url.hostname,
288	      port: IMPORT_LIMITS.PORT,
289	      path: `${url.pathname}${url.search}`,
290	      method: "GET",
291	      // TLS still validates the real hostname; only the ROUTE is pinned.
292	      servername: url.hostname,
293	      rejectUnauthorized: true,
294	      // No pooling. A shared agent could hand us a socket opened for a
295	      // different (or previously valid) resolution of the same host name.
296	      agent: false,
297	      lookup: pinnedLookup(address, family),
298	      timeout: Math.min(IMPORT_LIMITS.CONNECT_TIMEOUT_MS, budget),
299	      headers: {
300	        // Set explicitly rather than left to Node, so it is obvious in review
301	        // that the wire request names the hostname while the socket goes to the
302	        // pinned address.
303	        Host: url.host,
304	        "User-Agent": USER_AGENT,
305	        Accept: "text/html,text/plain;q=0.5",
306	        "Accept-Language": "en",
307	        // Compressed bodies would make the byte cap meaningless: 2MB of gzip is
308	        // a great deal more than 2MB of HTML, and a decompression bomb is the
309	        // obvious follow-up. Identity costs bandwidth we can afford.
310	        "Accept-Encoding": "identity",
311	        Connection: "close",
312	      },
313	    });
314	
315	    const hardStop = setTimeout(() => {
316	      req.destroy(new Error("total deadline expired"));
317	    }, budget);
318	
319	    const finish = (fn: () => void) => {
320	      clearTimeout(hardStop);
321	      fn();
322	    };
323	
324	    req.on("timeout", () => {
325	      req.destroy(new Error("connect timed out"));
326	    });
327	    req.on("error", (err) => finish(() => reject(err)));
328	
329	    req.on("response", (res) => {
330	      const chunks: Buffer[] = [];
331	      let received = 0;
332	
333	      const declared = Number(res.headers["content-length"] ?? "");
334	      if (Number.isFinite(declared) && declared > maxBytes) {
335	        res.destroy();
336	        req.destroy();
337	        finish(() => reject(new Error("response too large")));
338	        return;
339	      }
340	
341	      res.on("data", (chunk: Buffer) => {
342	        received += chunk.length;
343	        if (received > maxBytes) {
344	          res.destroy();
345	          req.destroy();
346	          finish(() => reject(new Error("response too large")));
347	          return;
348	        }
349	        chunks.push(chunk);
350	      });
351	      res.on("aborted", () => finish(() => reject(new Error("connection aborted"))));
352	      res.on("error", (err) => finish(() => reject(err)));
353	      res.on("end", () =>
354	        finish(() =>
355	          resolve({
356	            status: res.statusCode ?? 0,
357	            headers: res.headers,
358	            body: Buffer.concat(chunks),
359	            address,
360	          }),
361	        ),
362	      );
363	    });
364	
365	    req.end();
366	  });
367	}
368	
369	// ---------------------------------------------------------------------------
370	// Decoding
371	// ---------------------------------------------------------------------------
372	
373	/**
