400	/**
401	 * Does the site's robots.txt permit us to read this path?
402	 *
403	 * Checked because we are a bot arriving uninvited at somebody's server, and the
404	 * cheapest way to be a good one is to read the file that says what they want.
405	 * It is also self-interested: the current-site case is a user importing their
406	 * own site, and a user whose own robots.txt blocks us gets a clear message
407	 * rather than a mysterious failure.
408	 *
409	 * Behaviour on failure follows RFC 9309 in the direction that does not punish
410	 * ordinary sites: 4xx or no file means allow (most sites have no robots.txt),
411	 * a network error means allow (we are one request, not a crawl), and 5xx means
412	 * refuse, because a server explicitly failing to serve its own policy is the
413	 * one case where guessing is rude.
414	 *
415	 * The fetch itself goes through exactly the same pinned-address machinery as
416	 * the page. It is not a side door: an unvalidated robots fetch would be an SSRF
417	 * with a friendlier name.
418	 */
419	async function robotsAllows(url: URL, address: string, family: number, deadline: number): Promise<boolean> {
420	  const robotsUrl = new URL("/robots.txt", url);
421	  let hop: Hop;
422	  try {
423	    hop = await getOnce(robotsUrl, address, family, IMPORT_LIMITS.MAX_ROBOTS_BYTES, deadline);
424	  } catch {
425	    return true;
426	  }
427	  if (hop.status >= 500) return false;
428	  if (hop.status !== 200) return true;
429	
430	  const text = decodeBody(hop.body, contentTypeOf(hop));
431	  return robotsPermits(text, `${url.pathname}${url.search}`);
432	}
