434	/**
435	 * A deliberately small robots.txt reader: group the file by `User-agent`, take
436	 * the group that names us if there is one and the `*` group otherwise, and
437	 * apply longest-match-wins between Allow and Disallow (RFC 9309 §2.2.2).
438	 *
439	 * Exported so it can be tested without a network.
440	 */
441	export function robotsPermits(text: string, path: string): boolean {
442	  const groups = new Map<string, string[]>();
443	  let current: string[] = [];
444	  let inGroup = false;
445	
446	  for (const rawLine of text.slice(0, IMPORT_LIMITS.MAX_ROBOTS_BYTES).split(/\r?\n/)) {
447	    const line = rawLine.split("#")[0].trim();
448	    if (!line) continue;
449	    const colon = line.indexOf(":");
450	    if (colon === -1) continue;
451	    const field = line.slice(0, colon).trim().toLowerCase();
452	    const value = line.slice(colon + 1).trim();
453	
454	    if (field === "user-agent") {
455	      const agent = value.toLowerCase();
456	      if (!inGroup) current = [];
457	      inGroup = true;
458	      if (!groups.has(agent)) groups.set(agent, current);
459	      else current = groups.get(agent) as string[];
460	      continue;
461	    }
462	    if (field === "allow" || field === "disallow") {
463	      inGroup = false;
464	      current.push(`${field}:${value}`);
465	    }
466	  }
467	
468	  const rules = groups.get(ROBOTS_TOKEN) ?? groups.get("*");
469	  if (!rules) return true;
470	
471	  let bestLength = -1;
472	  let bestAllows = true;
473	  for (const rule of rules) {
474	    const colon = rule.indexOf(":");
475	    const kind = rule.slice(0, colon);
476	    const pattern = rule.slice(colon + 1);
477	    // An empty Disallow means "nothing is disallowed" and is not a match.
478	    if (kind === "disallow" && pattern === "") continue;
479	    if (!matchesRobotsPattern(pattern, path)) continue;
480	    // Ties go to Allow, per the RFC.
481	    if (pattern.length > bestLength || (pattern.length === bestLength && kind === "allow")) {
482	      bestLength = pattern.length;
483	      bestAllows = kind === "allow";
484	    }
485	  }
486	  return bestAllows;
487	}
488	
489	/** `*` wildcards and a trailing `$` anchor, which is all robots.txt defines. */
490	function matchesRobotsPattern(pattern: string, path: string): boolean {
491	  if (pattern === "") return true;
492	  const anchored = pattern.endsWith("$");
493	  const body = anchored ? pattern.slice(0, -1) : pattern;
494	  const escaped = body.replace(/[.+?^${}()|[\]\\]/g, "\\$&").replace(/\*/g, ".*");
495	  return new RegExp(`^${escaped}${anchored ? "$" : ""}`).test(path);
496	}
