498	// ---------------------------------------------------------------------------
499	// The public entry point
500	// ---------------------------------------------------------------------------
501	
502	/**
503	 * Fetch one page's HTML, or refuse and say why.
504	 *
505	 * Every failure returns a `code` so the route can decide the status and a
506	 * `reason` written for the person who typed the URL. The reason for a blocked
507	 * address is deliberately the same sentence whichever private range it landed
508	 * in: a caller probing our network should not be able to read our answers as a
509	 * map of it.
510	 */
511	export async function fetchSiteHtml(raw: string): Promise<FetchResult> {
512	  if (!isUrlImportConfigured()) {
513	    return {
514	      ok: false,
515	      code: "blocked",
516	      reason: "Importing by URL isn't switched on. Paste the text from your site instead.",
517	    };
518	  }
519	
520	  const first = validateImportUrl(raw);
521	  if (!first.ok) return { ok: false, code: "blocked", reason: first.reason };
522	
523	  const deadline = Date.now() + IMPORT_LIMITS.TOTAL_TIMEOUT_MS;
524	  const hops: string[] = [];
525	  const addresses: string[] = [];
526	
527	  let url = first.url;
528	  let robotsChecked = "";
529	
530	  for (let hop = 0; hop <= IMPORT_LIMITS.MAX_REDIRECTS; hop++) {
531	    // Fresh resolution and fresh classification on EVERY hop. Hop three gets
532	    // exactly the scrutiny hop zero did.
533	    const resolved = await resolveOne(url.hostname, deadline);
534	    if (!resolved.ok) return { ok: false, code: resolved.code, reason: resolved.reason };
535	
536	    hops.push(url.toString());
537	    addresses.push(resolved.address);
538	
539	    // Once per host in the chain, not once per request: a redirect within the
540	    // same site should not cost a second robots fetch out of the same 10s.
541	    if (robotsChecked !== url.hostname) {
542	      const allowed = await robotsAllows(url, resolved.address, resolved.family, deadline);
543	      robotsChecked = url.hostname;
544	      if (!allowed) {
545	        return {
546	          ok: false,
547	          code: "robots",
548	          reason: `${url.hostname}'s robots.txt asks bots not to read that page. Paste the text instead.`,
549	        };
550	      }
551	    }
552	
553	    let response: Hop;
554	    try {
555	      response = await getOnce(
556	        url,
557	        resolved.address,
558	        resolved.family,
559	        IMPORT_LIMITS.MAX_HTML_BYTES,
560	        deadline,
561	      );
562	    } catch (err) {
563	      const message = err instanceof Error ? err.message : "";
564	      if (message === "response too large") {
565	        return { ok: false, code: "unusable", reason: "That page is too big to read." };
566	      }
567	      return {
568	        ok: false,
569	        code: "unreachable",
570	        reason: "We couldn't reach that page. Check the address, or paste the text instead.",
571	      };
572	    }
573	
574	    if (response.status >= 300 && response.status < 400) {
575	      const location = response.headers.location;
576	      const target = Array.isArray(location) ? location[0] : location;
577	      if (!target) {
578	        return { ok: false, code: "unusable", reason: "That page redirected nowhere." };
579	      }
580	      if (hop === IMPORT_LIMITS.MAX_REDIRECTS) {
581	        return { ok: false, code: "unusable", reason: "That address redirects too many times." };
582	      }
583	      const next = resolveRedirect(target, url);
584	      if (!next.ok) return { ok: false, code: "blocked", reason: next.reason };
585	      url = next.url;
586	      continue;
587	    }
588	
589	    if (response.status !== 200) {
590	      return {
591	        ok: false,
592	        code: "unusable",
593	        reason: `That page answered with a ${response.status}. Check the address, or paste the text instead.`,
594	      };
595	    }
596	
597	    const contentType = contentTypeOf(response);
598	    // Allowlist, and it is checked on the FINAL hop's response rather than
599	    // anywhere earlier: a redirect chain that ends at an internal service
600	    // answering `application/json` stops here even if every address passed.
601	    if (!/^\s*text\/html\b/i.test(contentType)) {
602	      return {
603	        ok: false,
604	        code: "unusable",
605	        reason: "That address isn't an HTML page. Give us the address of the page itself.",
606	      };
607	    }
608	
609	    return {
610	      ok: true,
611	      html: decodeBody(response.body, contentType),
612	      finalUrl: url.toString(),
613	      hops,
614	      addresses,
615	    };
616	  }
617	
618	  return { ok: false, code: "unusable", reason: "That address redirects too many times." };
619	}
